&Title = 'Relatório de Entrada e Saida de Produto(s)' &AppName = 'Sistema de Gestão de Alimentação Escolar' &numeroLinha = 0 &Page = 0 &desTipo = ''
if &inTipo = 'T' &desTipo = 'Todos' endif
if &inTipo = 'E' &desTipo = 'Entrada' endif
if &inTipo = 'S' &desTipo = 'Saida' endif
LoadWWPContext.Call(&WWPContext) &prefCodigo = &WWPContext.prefCodigo
// Buscando a Unidade Edcuativa
Do 'Cabecalho'
for each trnslocal order prefCodigo, locCodigo where locStatus = 'A' where prefCodigo = &prefCodigo where locCodigo = &locCodigo when &locCodigo<>0 &locDescricao = Upper( locDescricao ) print printUnidade //Do 'Cabecalho'
// Buscando o produto for each trnsprodutos order prefCodigo, prodDescricao where prodStatus = 'A' where prefCodigo = &prefCodigo where StrSearch(&varSelecao,'[' + prodCodigo.ToString().Trim()+']')>0
&prodCodigo = prodCodigo &prodDescricao = upper( prodDescricao )
// Buscando dados da Distribuição de produtos if &inTipo in ('E','T') for each trnsdistribuicao, trnsdistribuicaoitens order prefCodigo, distDataEnvio where prefCodigo = &prefCodigo where distLocalDestino = locCodigo where distDataEnvio >= &dateIncial and distDataEnvio <= &dateFinal where distItemProduto = &prodCodigo where distStatus = 'A' where distReceber = 'S' where distItemQuantidade>0 &movData = distDataEnvio &movDados = 'Guia nr. ' + distCodigo.ToString().Trim() &movTipo = 'Entrada' &movQtde = distItemQuantidade print printDadosMovimentacao //Do 'Cabecalho' endfor endif
// Buscando dados do Consumo if &inTipo in ('S','T') for each TRNSMapaUE order prefCodigo, mapaUeData where prefCodigo = &prefCodigo where mapaUeLocCodigo = locCodigo where mapaUeData >= &dateIncial where mapaUeData <= &dateFinal where mapaUeProdCodigo = &prodCodigo &movData = mapaUeData &movDados = 'Mapa Consumo nr. ' + mapaUeCodigo.ToString().Trim() &movTipo = 'Saida' &movQtde = mapaUeQuantidade print printDadosMovimentacao // Do 'Cabecalho' endFor Endif endFor endFor
sub 'Cabecalho' if &numeroLinha=0 or &numeroLinha>=35 For each where prefCodigo = &prefCodigo &prefLogo = prefLogo print printCabecalho endFor &numeroLinha=1 else &numeroLinha +=1 endif endSub
